 const projected=useMemo(()=>{const cy=Math.cos(camera.yaw),sy=Math.sin(camera.yaw),cx=Math.cos(camera.pitch),sx=Math.sin(camera.pitch);return mesh.vertices.map(([x,y,z])=>{const rx=x*cy+z*sy,rz=-x*sy+z*cy,ry=y*cx-rz*sx,depth=y*sx+rz*cx;return {x:300+camera.panX+rx*118*camera.zoom,y:250+camera.panY-ry*118*camera.zoom,depth}})},[mesh,camera])
