 const extractPreview=(img,threshold)=>{setExtract(v=>({...v,threshold}));requestAnimationFrame(()=>{const scale=Math.min(1,512/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const ctx=canvas.getContext('2d'),im=ctx.getImageData(0,0,canvas.width,canvas.height),px=im.data,w=canvas.width,h=canvas.height,samples=[];for(let x=0;x<w;x+=Math.max(1,Math.floor(w/24)))for(const y of [0,h-1]){const i=(y*w+x)*4;samples.push([px[i],px[i+1],px[i+2]])}for(let y=0;y<h;y+=Math.max(1,Math.floor(h/24)))for(const x of [0,w-1]){const i=(y*w+x)*4;samples.push([px[i],px[i+1],px[i+2]])}const bg=[0,1,2].map(k=>samples.map(a=>a[k]).sort((a,b)=>a-b)[Math.floor(samples.length/2)]),limit=threshold*2.4;for(let i=0;i<px.length;i+=4){const d=Math.hypot(px[i]-bg[0],px[i+1]-bg[1],px[i+2]-bg[2]);if(d<limit)px[i+3]=0;else px[i+3]=Math.round(px[i+3]*Math.min(1,(d-limit+18)/30))}ctx.putImageData(im,0,0);setExtract(v=>({...v,preview:canvas.toDataURL('image/png')}))})}
 const requestHeaders={Authorization:`Bearer ${token}`}
