 useEffect(()=>{loadSharedCatalogue()},[token])
 const saveToCatalogue=async motif=>{if(!catalogueConsent)return;const base64=motif.data?.split(',')[1]||'';const estimatedBytes=Math.floor(base64.length*3/4);if(estimatedBytes>8*1024*1024){setCatalogueNotice('This motif is larger than 8 MB; reduce the image before sharing.');return}setSavingMotif(motif.id);setCatalogueNotice('');try{const response=await fetch('/api/storage/shared/stone-sleeper/catalogue',{method:'POST',headers:{...requestHeaders,'Content-Type':'application/json'},body:JSON.stringify({id:crypto.randomUUID(),name:motif.name,origin:motif.origin||'draw',image:motif.data})});if(!response.ok){let detail='Could not save this motif.';try{detail=(await response.json()).detail||detail}catch{}throw new Error(detail)}await loadSharedCatalogue();setCatalogueNotice(`“${motif.name}” is now in the shared catalogue and visible to all users of this instance.`)}catch(err){setCatalogueNotice(`Motif not saved: ${err.message}`)}finally{setSavingMotif(null)}}
